fn multiply37(label:&str,v:&[Series],base:&[Series],d:&[Series],n:u64,table:&[[u8;32];32],out:&mut impl Write)->Vec<Series>{assert!(n>0);let top=63-n.leading_zeros();let mut value=d.to_vec();for k in (0..top).rev(){value=add37(&format!("{label}-double-{k}"),v,base,&value,&value,table,out);if(n>>k)&1!=0{value=add37(&format!("{label}-add-{k}"),v,base,&value,d,table,out);}}value}
fn main(){let args:Vec<String>=env::args().collect();assert_eq!(args.len(),6);let spaces=read(&args[1]);let v=&spaces[2];let base=&spaces[0];let zero=&spaces[1];let e=read_class37(&args[2]);let e2=read_class37(&args[3]);let metadata=fs::read_to_string(&args[4]).unwrap();let n:u64=metadata.split("number normMinus37=").nth(1).unwrap().split(';').next().unwrap().parse().unwrap();assert_eq!(n,3721);assert_eq!(61u64*61,n);assert_ne!(n%11,0);assert_eq!(121*n,450241);series_basis36(&e);series_basis36(&e2);let mut table=[[0u8;32];32];for a in 0..32{for b in 0..32{table[a][b]=field(a as u8,b as u8);assert_eq!(table[a][b],field_independent(a as u8,b as u8));}}
 fs::create_dir(&args[5]).unwrap();let mut out=BufWriter::new(fs::File::create(format!("{}/isolation-certificates.txt",args[5])).unwrap());
 let f=multiply37("cofactor-first",v,base,&e,n,&table,&mut out);let intermediate=multiply37("cofactor-second-61a",v,base,&e2,61,&table,&mut out);let f2=multiply37("cofactor-second-61b",v,base,&intermediate,61,&table,&mut out);assert!(same37("cofactor-two-expressions",v,&f,&f2,&table,&mut out));
 let f_zero=same37("cofactor-versus-zero",v,&f,zero,&table,&mut out);let sixty_one_zero=same37("sixty-one-versus-zero",v,&intermediate,zero,&table,&mut out);
 let f11=multiply37("cofactor-eleven",v,base,&f,11,&table,&mut out);let f121=multiply37("cofactor-one-twenty-one",v,base,&f11,11,&table,&mut out);let eleven_zero=same37("eleven-cofactor-versus-zero",v,&f11,zero,&table,&mut out);let bridge_annihilator=same37("bridge-annihilator-versus-zero",v,&f121,zero,&table,&mut out);
 if f_zero{assert!(eleven_zero&&bridge_annihilator);}if sixty_one_zero{assert!(f_zero);}save37(&args[5],"cofactor",&f);save37(&args[5],"cofactor-second",&f2);save37(&args[5],"sixty-one",&intermediate);save37(&args[5],"eleven-cofactor",&f11);save37(&args[5],"annihilator",&f121);out.flush().unwrap();
 fs::write(format!("{}/isolation-result.txt",args[5]),format!("cofactor=3721\ncofactor_class_principal={f_zero}\nsixty_one_class_principal={sixty_one_zero}\neleven_cofactor_principal={eleven_zero}\nbridge_annihilator_principal={bridge_annihilator}\nindependent_cofactor_expressions_equal=true\n")).unwrap();println!("ISOLATE37_RESULT cofactor=3721 cofactor_mod11=3 cofactor_class_principal={f_zero} sixty_one_class_principal={sixty_one_zero} eleven_cofactor_principal={eleven_zero} bridge_annihilator_principal={bridge_annihilator} independent_cofactor_expressions_equal=true all_generator_memberships=checked independent_products=all intended_sign_factor_evaluated=false");println!("ISOLATE37_ALL_CHECKS_PASS");}
